    {
      "id": "reflection.effort_sets",
      "tiers": [
        {
          "id": "reflection.effort_sets:t1",
          "title": "Микрофон для ощущений",
          "phrase": "Ты сохранил свою оценку усилия после 3 подходов. Ощущения получили микрофон — железо, не перебивай!",
          "imagePrompt": "A small microphone reporter with mitten hands leans toward a resting dumbbell, holding an open pocket notebook. Three folded feedback cards stand beside the dumbbell like tiny audience seats.",
